(** 0RB---_0RC0LD_1LD1RC_0LA1LB *)
(** 0RB---_0RC0LD_1LD1RC_0LA1LB -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB____0RC0LD_1LD1RC_0LA1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => None
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DL StB end.

(** Its mirror 0LB---_0LC0RD_1RD1LC_0RA1RB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB____0RC0LD_1LD1RC_0LA1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => None
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB____0RC0LD_1LD1RC_0LA1LB : list Instr := [(StA, S1)].
Definition tmw_0RB____0RC0LD_1LD1RC_0LA1LB : TM := tm_wrap_trs tmm_0RB____0RC0LD_1LD1RC_0LA1LB pins_0RB____0RC0LD_1LD1RC_0LA1LB.
Local Notation tm := tmw_0RB____0RC0LD_1LD1RC_0LA1LB.

Lemma mirror_ok_0RB____0RC0LD_1LD1RC_0LA1LB : mirror_tm tm_0RB____0RC0LD_1LD1RC_0LA1LB = tmm_0RB____0RC0LD_1LD1RC_0LA1LB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

