Lemma geo_0RB____0RC0LD_1LD1RC_0LA1LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB____0RC0LD_1LD1RC_0LA1LB) = lift (Cc (Pos.succ p)).
