  - exists (4 * j + 9), (cden [] [] j BB1_0RB____0RC0LD_1LD1RC_0LA1LB).
    split; [lia|]. split; [| exact (gbo_0RB____0RC0LD_1LD1RC_0LA1LB j)].
    rewrite (gso_0RB____0RC0LD_1LD1RC_0LA1LB p j E).
    exact (srun_sound tm true true chb_0RB____0RC0LD_1LD1RC_0LA1LB B0_0RB____0RC0LD_1LD1RC_0LA1LB BB1_0RB____0RC0LD_1LD1RC_0LA1LB 4 9
             run_boot_0RB____0RC0LD_1LD1RC_0LA1LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_0RB____0RC0LD_1LD1RC_0LA1LB).
    split; [| exact (geo_0RB____0RC0LD_1LD1RC_0LA1LB p j E)].
    rewrite (gxi_0RB____0RC0LD_1LD1RC_0LA1LB j).
    exact (srun_sound tm true true che_0RB____0RC0LD_1LD1RC_0LA1LB BE0_0RB____0RC0LD_1LD1RC_0LA1LB B1_0RB____0RC0LD_1LD1RC_0LA1LB 4 11
             run_exit_0RB____0RC0LD_1LD1RC_0LA1LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB____0RC0LD_1LD1RC_0LA1LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
