(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LA_0RC0LC_1LD0RB_1LD0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LA_0RC0LC_1LD0RB_1LD0RA.
Proof.
