Lemma geo_1RB0LA_0RC0LC_1LD0RB_1LD0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LA_0RC0LC_1LD0RB_1LD0RA) = lift (Cc (Pos.succ p)).
