(** ** The lap *)

Lemma lap_1RB0LA_0RC0LD_0RD0RB_1LD0RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
