(** ** Bootstrap *)

Lemma boot_1RB0LA_0RC0LD_0RD0RB_1LD0RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
