(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LA_0RC0LD_0RD0RB_1LD0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LA_0RC0LD_0RD0RB_1LD0RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LA_0RC0LD_0RD0RB_1LD0RA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LA_0RC0LD_0RD0RB_1LD0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LA_0RC0LD_0RD0RB_1LD0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LA_0RC0LD_0RD0RB_1LD0RA t p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_1RB0LA_0RC0LD_0RD0RB_1LD0RA). split;
      [| exact (gbo_1RB0LA_0RC0LD_0RD0RB_1LD0RA j)].
    rewrite (gso_1RB0LA_0RC0LD_0RD0RB_1LD0RA p j E).
    exact (srun_sound tm true true chb_1RB0LA_0RC0LD_0RD0RB_1LD0RA B0_1RB0LA_0RC0LD_0RD0RB_1LD0RA BB1_1RB0LA_0RC0LD_0RD0RB_1LD0RA 4 4
             run_boot_1RB0LA_0RC0LD_0RD0RB_1LD0RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LA_0RC0LD_0RD0RB_1LD0RA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LA_0RC0LD_0RD0RB_1LD0RA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LA_0RC0LD_0RD0RB_1LD0RA : forall t, ~ In t pins_1RB0LA_0RC0LD_0RD0RB_1LD0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LA_0RC0LD_0RD0RB_1LD0RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 4; SCycR 2; SWin 3]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LA_0RC0LD_0RD0RB_1LD0RA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LA_0RC0LD_0RD0RB_1LD0RA [SWin 4; SCycL 2 0; SWin 1; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LA_0RC0LD_0RD0RB_1LD0RA
      with (l := [SCycL 2 0; SWin 4; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LA_0RC0LD_0RD0RB_1LD0RA : NeverQuasiHaltsTr tmm_1RB0LA_0RC0LD_0RD0RB_1LD0RA.
Proof.
