Definition mk_1RB0LA_0RC0LD_1LD0RB_1LD0RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LA_0RC0LD_1LD0RB_1LD0RA.

(** 1RB0LA_0RC0LD_1LD0RB_1LD0RA *)
(** 1RB0LA_0RC0LD_1LD0RB_1LD0RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LA_0RC0LD_1LD0RB_1LD0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S0 DR StA end.

(** Its mirror 1LB0RA_0LC0RD_1RD0LB_1RD0LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LA_0RC0LD_1LD0RB_1LD0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S1 DR StD | StD, S1 => mk S0 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LA_0RC0LD_1LD0RB_1LD0RA : list Instr := [].
Definition tmw_1RB0LA_0RC0LD_1LD0RB_1LD0RA : TM := tm_wrap_trs tmm_1RB0LA_0RC0LD_1LD0RB_1LD0RA pins_1RB0LA_0RC0LD_1LD0RB_1LD0RA.
