(** ** The lap *)

Lemma lap_1RB0LA_0RC0LD_1LD0RB_1LD0RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LA_0RC0LD_1LD0RB_1LD0RA B0_1RB0LA_0RC0LD_1LD0RB_1LD0RA B1_1RB0LA_0RC0LD_1LD0RB_1LD0RA 4 10 p j' [] []).
    + exact run_ovf_1RB0LA_0RC0LD_1LD0RB_1LD0RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j' E).
    + exact (geo_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LA_0RC0LD_1LD0RB_1LD0RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LA_0RC0LD_1LD0RB_1LD0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LA_0RC0LD_1LD0RB_1LD0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LA_0RC0LD_1LD0RB_1LD0RA = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j (Jp q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LA_0RC0LD_1LD0RB_1LD0RA p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LA_0RC0LD_1LD0RB_1LD0RA : forall t, ~ In t pins_1RB0LA_0RC0LD_1LD0RB_1LD0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LA_0RC0LD_1LD0RB_1LD0RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* B1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LA_0RC0LD_1LD0RB_1LD0RA (StB, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LA_0RC0LD_1LD0RB_1LD0RA [SWin 4; SCycL 2 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 4; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 4; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LA_0RC0LD_1LD0RB_1LD0RA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0LA_0RC0LD_1LD0RB_1LD0RA : NeverQuasiHaltsTr tmm_1RB0LA_0RC0LD_1LD0RB_1LD0RA.
Proof.
  apply (glue_neverqhtr tmm_1RB0LA_0RC0LD_1LD0RB_1LD0RA pins_1RB0LA_0RC0LD_1LD0RB_1LD0RA Cc 1).
