(** ** The lap *)

Lemma lap_1RB0LA_0RC1RA_0LD0RB_1LD1LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
