(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LA_1LB1LC_1RD0LC_0RD0RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0LA_1LB1LC_1RD0LC_0RD0RA /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0LA_1LB1LC_1RD0LC_0RD0RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LA_1LB1LC_1RD0LC_0RD0RA, cden, Z0_1RB0LA_1LB1LC_1RD0LC_0RD0RA, Z1_1RB0LA_1LB1LC_1RD0LC_0RD0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LA_1LB1LC_1RD0LC_0RD0RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0LA_1LB1LC_1RD0LC_0RD0RA /\
  lift (cden (Kp q0 ++ [S0]) [] j P1_1RB0LA_1LB1LC_1RD0LC_0RD0RA) = lift (Cc (Pos.succ p)).
