Lemma lapi_1RB0LA_1LB1LC_1RD0LC_0RD0RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LA_1LB1LC_1RD0LC_0RD0RA p q0 E) as (HA & HB).
    exists (0 * 0 + 6), (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0LA_1LB1LC_1RD0LC_0RD0RA).
    split; [lia|]. split; [| exact HB].
