    exact (srun_sound tm false true chz_1RB0LA_1LB1LC_1RD0LC_0RD0RA Z0_1RB0LA_1LB1LC_1RD0LC_0RD0RA Z1_1RB0LA_1LB1LC_1RD0LC_0RD0RA 0 6
             run_z_1RB0LA_1LB1LC_1RD0LC_0RD0RA (Kp q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB0LA_1LB1LC_1RD0LC_0RD0RA p j' q0 E) as (HA & HB).
    exists (2 * j' + 8), (cden (Kp q0 ++ [S0]) [] j' P1_1RB0LA_1LB1LC_1RD0LC_0RD0RA).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB0LA_1LB1LC_1RD0LC_0RD0RA P0_1RB0LA_1LB1LC_1RD0LC_0RD0RA P1_1RB0LA_1LB1LC_1RD0LC_0RD0RA 2 8
             run_p_1RB0LA_1LB1LC_1RD0LC_0RD0RA (Kp q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
