Lemma geo_1RB0LA_1LB1LC_1RD0LC_0RD0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LA_1LB1LC_1RD0LC_0RD0RA) = lift (Cc (Pos.succ p)).
