(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0LA_1LC0RB_0LC0RD_1RD1LA /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0LA_1LC0RB_0LC0RD_1RD1LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LA_1LC0RB_0LC0RD_1RD1LA, cden, Z0_1RB0LA_1LC0RB_0LC0RD_1RD1LA, Z1_1RB0LA_1LC0RB_0LC0RD_1RD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0LA_1LC0RB_0LC0RD_1RD1LA /\
  cden (Kp q0 ++ [S0]) [] j P1_1RB0LA_1LC0RB_0LC0RD_1RD1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LA_1LC0RB_0LC0RD_1RD1LA, cden, P0_1RB0LA_1LC0RB_0LC0RD_1RD1LA, P1_1RB0LA_1LC0RB_0LC0RD_1RD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LA_1LC0RB_0LC0RD_1RD1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LA_1LC0RB_0LC0RD_1RD1LA Z0_1RB0LA_1LC0RB_0LC0RD_1RD1LA Z1_1RB0LA_1LC0RB_0LC0RD_1RD1LA 0 4
               run_z_1RB0LA_1LC0RB_0LC0RD_1RD1LA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LA_1LC0RB_0LC0RD_1RD1LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LA_1LC0RB_0LC0RD_1RD1LA P0_1RB0LA_1LC0RB_0LC0RD_1RD1LA P1_1RB0LA_1LC0RB_0LC0RD_1RD1LA 4 8
               run_p_1RB0LA_1LC0RB_0LC0RD_1RD1LA (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LA_1LC0RB_0LC0RD_1RD1LA.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB0LA_1LC0RB_0LC0RD_1RD1LA, cden, B0_1RB0LA_1LC0RB_0LC0RD_1RD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LA_1LC0RB_0LC0RD_1RD1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LA_1LC0RB_0LC0RD_1RD1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LA_1LC0RB_0LC0RD_1RD1LA
             = (StA, (rep [S0] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB0LA_1LC0RB_0LC0RD_1RD1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LA_1LC0RB_0LC0RD_1RD1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LA_1LC0RB_0LC0RD_1RD1LA. reflexivity.
