Lemma geo_1RB0LA_1LC0RB_1LD1RB_0LC0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LA_1LC0RB_1LD1RB_0LC0RA) = lift (Cc (Pos.succ p)).
