(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LA_1LC0RB_1LD1RB_0LC0RA : forall j, lift (cden [] [] j BB1_1RB0LA_1LC0RB_1LD1RB_0LC0RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LA_1LC0RB_1LD1RB_0LC0RA = (StD, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold cden, BB1_1RB0LA_1LC0RB_1LD1RB_0LC0RA, sden;
