(** ** The lap *)

Lemma lap_1RB0LA_1LC0RB_1RD1LA_0LA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
