  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LA_1LC0RB_1RD1LA_0LA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LA_1LC0RB_1RD1LA_0LA1RC B0_1RB0LA_1LC0RB_1RD1LA_0LA1RC B1_1RB0LA_1LC0RB_1RD1LA_0LA1RC 6 20 p j' [] []).
    + exact run_ovf_1RB0LA_1LC0RB_1RD1LA_0LA1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LA_1LC0RB_1RD1LA_0LA1RC p j' E).
    + exact (geo_1RB0LA_1LC0RB_1RD1LA_0LA1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LA_1LC0RB_1RD1LA_0LA1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LA_1LC0RB_1RD1LA_0LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LA_1LC0RB_1RD1LA_0LA1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LA_1LC0RB_1RD1LA_0LA1RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LA_1LC0RB_1RD1LA_0LA1RC : forall t, ~ In t pins_1RB0LA_1LC0RB_1RD1LA_0LA1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LA_1LC0RB_1RD1LA_0LA1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2; SCycL 4 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2; SCycL 4 0; SWin 4; SWinL 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2; SCycL 4 0; SWin 4; SWinL 4; SCycR 2; SWin 1; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2; SCycL 4 0; SWin 4; SWinL 4; SCycR 2; SWin 1; SWinR 5] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LA_1LC0RB_1RD1LA_0LA1RC [SWinR 2; SCycL 4 0; SWin 4; SWinL 4; SCycR 2; SWin 1; SWinR 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB0LA_1LC0RB_1RD1LA_0LA1RC : NeverQuasiHaltsTr tm_1RB0LA_1LC0RB_1RD1LA_0LA1RC.
