  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (10 * j + 13), (cden [] [] j BB1_1RB0LA_1LC0RD_0LA1LD_0RB1RA).
      split; [lia|]. split; [| exact (gbo_1RB0LA_1LC0RD_0LA1LD_0RB1RA j)].
