               run_boot_1RB0LA_1LC0RD_0LA1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LA_1LC0RD_0LA1LD_0RB1RA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (10 * j + 12), (cden [] [] j BM1_1RB0LA_1LC0RD_0LA1LD_0RB1RA).
      split; [| exact (gbo2_1RB0LA_1LC0RD_0LA1LD_0RB1RA j)].
      rewrite (gxi_1RB0LA_1LC0RD_0LA1LD_0RB1RA j).
      exact (srun_sound tm true true chm_1RB0LA_1LC0RD_0LA1LD_0RB1RA BM0_1RB0LA_1LC0RD_0LA1LD_0RB1RA BM1_1RB0LA_1LC0RD_0LA1LD_0RB1RA 10 12
               run_shift_1RB0LA_1LC0RD_0LA1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin3 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB0LA_1LC0RD_0LA1LD_0RB1RA p (pow2 j) (pow2 j));
