      split; [| exact (gbo3_1RB0LA_1LC0RD_0LA1LD_0RB1RA j)].
      rewrite (gxi2_1RB0LA_1LC0RD_0LA1LD_0RB1RA j).
      exact (srun_sound tm true true chm3_1RB0LA_1LC0RD_0LA1LD_0RB1RA BM30_1RB0LA_1LC0RD_0LA1LD_0RB1RA BM31_1RB0LA_1LC0RD_0LA1LD_0RB1RA 10 18
               run_shift3_1RB0LA_1LC0RD_0LA1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB4 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin4 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin3 Cin4 lapin3_1RB0LA_1LC0RD_0LA1LD_0RB1RA p (pow2 j) (pow2 j));
        [exact HB3|].
      exists (10 * j + 12), (cden [] [] j BM41_1RB0LA_1LC0RD_0LA1LD_0RB1RA).
      split; [| exact (gbo4_1RB0LA_1LC0RD_0LA1LD_0RB1RA j)].
