  - destruct (lapi_1RB0LA_1LC0RD_0LA1LD_0RB1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LA_1LC0RD_0LA1LD_0RB1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LA_1LC0RD_0LA1LD_0RB1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
