(** ** The lap *)

Lemma lap_1RB0LA_1LC0RD_0LC1LD_0RB1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
