    apply (lap_of_run tm Cc true true cho_1RB0LA_1LC0RD_0LC1LD_0RB1RA B0_1RB0LA_1LC0RD_0LC1LD_0RB1RA B1_1RB0LA_1LC0RD_0LC1LD_0RB1RA 4 16 p j' [] []).
    + exact run_ovf_1RB0LA_1LC0RD_0LC1LD_0RB1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LA_1LC0RD_0LC1LD_0RB1RA p j' E).
    + exact (geo_1RB0LA_1LC0RD_0LC1LD_0RB1RA p j' E).
    + lia.
