  exists (10 * j + 12), (cden (Ap_Alph_010_110_1 q0 ++ [S0]) [] j A1_1RB0LA_1LC0RD_1LB1LD_0RB1RA).
  split; [lia|]. split; [| exact (gei_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j q0 E)].
  rewrite (gsi_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j q0 E).
  exact (srun_sound tm false true chi_1RB0LA_1LC0RD_1LB1LD_0RB1RA A0_1RB0LA_1LC0RD_1LB1LD_0RB1RA A1_1RB0LA_1LC0RD_1LB1LD_0RB1RA 10 12
           run_int_1RB0LA_1LC0RD_1LB1LD_0RB1RA (Ap_Alph_010_110_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
