(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LA_1LC0RD_1LB1LD_0RB1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB0LA_1LC0RD_1LB1LD_0RB1RA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (10 * j + 11), (cden [] [] j BB1_1RB0LA_1LC0RD_1LB1LD_0RB1RA).
      split; [lia|]. split; [| exact (gbo_1RB0LA_1LC0RD_1LB1LD_0RB1RA j)].
      rewrite (gso_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j E).
      exact (srun_sound tm true true chb_1RB0LA_1LC0RD_1LB1LD_0RB1RA B0_1RB0LA_1LC0RD_1LB1LD_0RB1RA BB1_1RB0LA_1LC0RD_1LB1LD_0RB1RA 10 11
               run_boot_1RB0LA_1LC0RD_1LB1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LA_1LC0RD_1LB1LD_0RB1RA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (10 * j + 18), (cden [] [] j BM1_1RB0LA_1LC0RD_1LB1LD_0RB1RA).
      split; [| exact (gbo2_1RB0LA_1LC0RD_1LB1LD_0RB1RA j)].
      rewrite (gxi_1RB0LA_1LC0RD_1LB1LD_0RB1RA j).
      exact (srun_sound tm true true chm_1RB0LA_1LC0RD_1LB1LD_0RB1RA BM0_1RB0LA_1LC0RD_1LB1LD_0RB1RA BM1_1RB0LA_1LC0RD_1LB1LD_0RB1RA 10 18
               run_shift_1RB0LA_1LC0RD_1LB1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin3 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB0LA_1LC0RD_1LB1LD_0RB1RA p (pow2 j) (pow2 j));
        [exact HB2|].
      exists (10 * j + 12), (cden [] [] j BM31_1RB0LA_1LC0RD_1LB1LD_0RB1RA).
      split; [| exact (gbo3_1RB0LA_1LC0RD_1LB1LD_0RB1RA j)].
      rewrite (gxi2_1RB0LA_1LC0RD_1LB1LD_0RB1RA j).
      exact (srun_sound tm true true chm3_1RB0LA_1LC0RD_1LB1LD_0RB1RA BM30_1RB0LA_1LC0RD_1LB1LD_0RB1RA BM31_1RB0LA_1LC0RD_1LB1LD_0RB1RA 10 12
               run_shift3_1RB0LA_1LC0RD_1LB1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB3.
  - exists (10 * j + 27), (cden [] [] j B1_1RB0LA_1LC0RD_1LB1LD_0RB1RA).
    split; [| exact (geo_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j E)].
    rewrite (gxi3_1RB0LA_1LC0RD_1LB1LD_0RB1RA j).
    exact (srun_sound tm true true che_1RB0LA_1LC0RD_1LB1LD_0RB1RA BE0_1RB0LA_1LC0RD_1LB1LD_0RB1RA B1_1RB0LA_1LC0RD_1LB1LD_0RB1RA 10 27
             run_exit_1RB0LA_1LC0RD_1LB1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LA_1LC0RD_1LB1LD_0RB1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LA_1LC0RD_1LB1LD_0RB1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 18 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LA_1LC0RD_1LB1LD_0RB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LA_1LC0RD_1LB1LD_0RB1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LA_1LC0RD_1LB1LD_0RB1RA p j [] []);
