(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LA_1LC0RD_1LC1LD_0RB1RA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB0LA_1LC0RD_1LC1LD_0RB1RA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (10 * j + 11), (cden [] [] j BB1_1RB0LA_1LC0RD_1LC1LD_0RB1RA).
      split; [lia|]. split; [| exact (gbo_1RB0LA_1LC0RD_1LC1LD_0RB1RA j)].
      rewrite (gso_1RB0LA_1LC0RD_1LC1LD_0RB1RA p j E).
      exact (srun_sound tm true true chb_1RB0LA_1LC0RD_1LC1LD_0RB1RA B0_1RB0LA_1LC0RD_1LC1LD_0RB1RA BB1_1RB0LA_1LC0RD_1LC1LD_0RB1RA 10 11
               run_boot_1RB0LA_1LC0RD_1LC1LD_0RB1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
