Lemma gsi_1RB0LA_1LC0RD_1RA1LD_0RB1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_010_110_1 q0 ++ [S0]) [] j A0_1RB0LA_1LC0RD_1RA1LD_0RB1RA.
