Import ListNotations.

Definition mk_1RB0LA_1LC0RD_1RC1LD_0RB1RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LA_1LC0RD_1RC1LD_0RB1RA.

(** 1RB0LA_1LC0RD_1RC1LD_0RB1RA *)
(** 1RB0LA_1LC0RD_1RC1LD_0RB1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LA_1LC0RD_1RC1LD_0RB1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StC | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S1 DR StA end.

(** Its mirror 1LB0RA_1RC0LD_1LC1RD_0LB1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LA_1LC0RD_1RC1LD_0RB1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DL StC | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LA_1LC0RD_1RC1LD_0RB1RA : list Instr := [].
Definition tmw_1RB0LA_1LC0RD_1RC1LD_0RB1RA : TM := tm_wrap_trs tmm_1RB0LA_1LC0RD_1RC1LD_0RB1RA pins_1RB0LA_1LC0RD_1RC1LD_0RB1RA.
Local Notation tm := tmw_1RB0LA_1LC0RD_1RC1LD_0RB1RA.

Lemma mirror_ok_1RB0LA_1LC0RD_1RC1LD_0RB1RA : mirror_tm tm_1RB0LA_1LC0RD_1RC1LD_0RB1RA = tmm_1RB0LA_1LC0RD_1RC1LD_0RB1RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LA_1LC0RD_1RC1LD_0RB1RA (p : positive) : cconf := (StA, (Ap_Alph_010_110_1 p ++ [S0], S0, [S1])).
