Lemma lapin_1RB0LA_1LC0RD_1RC1LD_0RB1RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (10 * i + 12), (cden (Ap_Alph_001_011_0 q0 ++ [S0;S1]) [] i AI1_1RB0LA_1LC0RD_1RC1LD_0RB1RA).
  split; [lia|]. split; [| exact (gen_1RB0LA_1LC0RD_1RC1LD_0RB1RA v i q0 E)].
