(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0LA_1LC0RD_1RC1LD_0RB1RA : forall j, lift (cden [] [] j BB1_1RB0LA_1LC0RD_1RC1LD_0RB1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LA_1LC0RD_1RC1LD_0RB1RA = (StB, ((rep [S0;S0;S1] j ++ [S0;S0;S1]) ++ [S0], S0, [S1]))).
  { unfold cden, BB1_1RB0LA_1LC0RD_1RC1LD_0RB1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S0;S0;S1] j ++ [S0;S0;S1], S0, [S1]))).
  { unfold Cin_1RB0LA_1LC0RD_1RC1LD_0RB1RA. rewrite epow2_1RB0LA_1LC0RD_1RC1LD_0RB1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LA_1LC0RD_1RC1LD_0RB1RA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LA_1LC0RD_1RC1LD_0RB1RA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB0LA_1LC0RD_1RC1LD_0RB1RA.
Proof.
  intro j.
  destruct (Alph_001_011_0.cview_none_Alph_001_011_0 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LA_1LC0RD_1RC1LD_0RB1RA, cden, BM0_1RB0LA_1LC0RD_1RC1LD_0RB1RA; cbn [c_st c_l c_h c_r].
