(** The lap ends on [S0;S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LA_1LC1LD_1LA0RC_0RB1RD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Dp q0 ++ [S0]) [] j A1_1RB0LA_1LC1LD_1LA0RC_0RB1RD) = lift (Cc (Pos.succ p)).
