(** ** The lap *)

Lemma lap_1RB0LA_1LC1LD_1LA0RC_0RB1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LA_1LC1LD_1LA0RC_0RB1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LA_1LC1LD_1LA0RC_0RB1RD B0_1RB0LA_1LC1LD_1LA0RC_0RB1RD B1_1RB0LA_1LC1LD_1LA0RC_0RB1RD 4 18 p j' [] []).
    + exact run_ovf_1RB0LA_1LC1LD_1LA0RC_0RB1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LA_1LC1LD_1LA0RC_0RB1RD p j' E).
    + exact (geo_1RB0LA_1LC1LD_1LA0RC_0RB1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LA_1LC1LD_1LA0RC_0RB1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
