(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LA_1LC1RD_1RC0RD_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A0_1RB0LA_1LC1RD_1RC0RD_1LA0RB.
Proof.
  intros p j q0 E. destruct (Alph_000_010_01.cview_some_Alph_000_010_01 p j q0 E) as (H1 & _).
  unfold Cc_1RB0LA_1LC1RD_1RC0RD_1LA0RB, cden, A0_1RB0LA_1LC1RD_1RC0RD_1LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0;S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LA_1LC1RD_1RC0RD_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A1_1RB0LA_1LC1RD_1RC0RD_1LA0RB) = lift (Cc (Pos.succ p)).
Proof.
