    apply (lap_of_run tm Cc true true cho_1RB0LA_1LC____1RD0RD_1LA1RC B0_1RB0LA_1LC____1RD0RD_1LA1RC B1_1RB0LA_1LC____1RD0RD_1LA1RC 4 12 p j' [] []).
