Lemma fireo_1RB0LB_0LC0RA_1LD0LD_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_0LC0RA_1LD0LD_1RA1LC = Some t ->
