Lemma fireo_1RB0LB_0RC1LA_1LB0RD_1LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_0RC1LA_1LB0RD_1LA1RC = Some t ->
