Lemma firex_1RB0LB_0RC1LA_1LB0RD_1LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LB_0RC1LA_1LB0RD_1LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LB_0RC1LA_1LB0RD_1LA1RC t p (pow2 j)).
  - exists (6 * j + 10), (cden [] [] j BB1_1RB0LB_0RC1LA_1LB0RD_1LA1RC). split;
      [| exact (gbo_1RB0LB_0RC1LA_1LB0RD_1LA1RC j)].
