Definition chp_1RB0LB_0RC1LA_1LB0RD_1LC1RC : list lstep := [SWin 2; SCycL 2 0; SWin 2; SCycR 4; SWin 4].

Lemma run_p_1RB0LB_0RC1LA_1LB0RD_1LC1RC : srun tm false true chp_1RB0LB_0RC1LA_1LB0RD_1LC1RC P0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some (P1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StB (mkS [S1;S1] [S1;S1] 1 0 [S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StB (mkS [] [S0;S1] 1 1 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StA *)
Definition Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC (v : positive) : cconf := (StA, (Ip v ++ [S1], S0, [S0;S1])).
Local Notation Cin := Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chn_1RB0LB_0RC1LA_1LB0RD_1LC1RC : list lstep := [SRotL 1; SWin 7; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1].

Lemma run_inner_1RB0LB_0RC1LA_1LB0RD_1LC1RC : srun tm false true chn_1RB0LB_0RC1LA_1LB0RD_1LC1RC AI0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some (AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chb_1RB0LB_0RC1LA_1LB0RD_1LC1RC : list lstep := [SWin 2; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1].

Lemma run_boot_1RB0LB_0RC1LA_1LB0RD_1LC1RC : srun tm true true chb_1RB0LB_0RC1LA_1LB0RD_1LC1RC B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some (BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, 6, 5).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition che_1RB0LB_0RC1LA_1LB0RD_1LC1RC : list lstep := [SRotL 1; SWin 7; SCycL 2 0; SWin 1; SWinL 3; SCycR 4; SWin 4; SFoldL 1].

Lemma run_exit_1RB0LB_0RC1LA_1LB0RD_1LC1RC : srun tm true true che_1RB0LB_0RC1LA_1LB0RD_1LC1RC BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some (B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, 6, 15).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Mp q0 ++ [S0]) [] 0 Z0_1RB0LB_0RC1LA_1LB0RD_1LC1RC /\
  cden (Mp q0 ++ [S0]) [] 0 Z1_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (MpCounter.cview_some_M p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, Z0_1RB0LB_0RC1LA_1LB0RD_1LC1RC, Z1_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Mp q0 ++ [S0]) [] j P0_1RB0LB_0RC1LA_1LB0RD_1LC1RC /\
  cden (Mp q0 ++ [S0]) [] j P1_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (MpCounter.cview_some_M p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, P0_1RB0LB_0RC1LA_1LB0RD_1LC1RC, P1_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LB_0RC1LA_1LB0RD_1LC1RC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LB_0RC1LA_1LB0RD_1LC1RC Z0_1RB0LB_0RC1LA_1LB0RD_1LC1RC Z1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 0 2
               run_z_1RB0LB_0RC1LA_1LB0RD_1LC1RC (Mp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LB_0RC1LA_1LB0RD_1LC1RC P0_1RB0LB_0RC1LA_1LB0RD_1LC1RC P1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 6 8
               run_p_1RB0LB_0RC1LA_1LB0RD_1LC1RC (Mp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC.
Proof.
  intros p j E. destruct (MpCounter.cview_none_M p j E) as (H1 & _).
  unfold Cc_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (MpCounter.cview_none_M p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC
             = (StB, (rep [S0;S1] (S j) ++ [S1;S1], S0, [S1]))).
  { unfold cden, B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S1] (S j) ++ [S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0LB_0RC1LA_1LB0RD_1LC1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LB_0RC1LA_1LB0RD_1LC1RC. reflexivity.
Qed.

Lemma gsn_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB0LB_0RC1LA_1LB0RD_1LC1RC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, AI0_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC).
  split; [lia|]. split; [| exact (gen_1RB0LB_0RC1LA_1LB0RD_1LC1RC v i q0 E)].
  rewrite (gsn_1RB0LB_0RC1LA_1LB0RD_1LC1RC v i q0 E).
  exact (srun_sound tm false true chn_1RB0LB_0RC1LA_1LB0RD_1LC1RC AI0_1RB0LB_0RC1LA_1LB0RD_1LC1RC AI1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 6 10
           run_inner_1RB0LB_0RC1LA_1LB0RD_1LC1RC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall j, lift (cden [] [] j BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC = (StA, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold cden, BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC. rewrite epow2_1RB0LB_0RC1LA_1LB0RD_1LC1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LB_0RC1LA_1LB0RD_1LC1RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LB_0RC1LA_1LB0RD_1LC1RC, cden, BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LB_0RC1LA_1LB0RD_1LC1RC p (pow2 j)).
  - exists (6 * j + 5), (cden [] [] j BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC).
    split; [lia|]. split; [| exact (gbo_1RB0LB_0RC1LA_1LB0RD_1LC1RC j)].
    rewrite (gso_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j E).
    exact (srun_sound tm true true chb_1RB0LB_0RC1LA_1LB0RD_1LC1RC B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 6 5
             run_boot_1RB0LB_0RC1LA_1LB0RD_1LC1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 15), (cden [] [] j B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC).
    split; [| exact (geo_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j E)].
    rewrite (gxi_1RB0LB_0RC1LA_1LB0RD_1LC1RC j).
    exact (srun_sound tm true true che_1RB0LB_0RC1LA_1LB0RD_1LC1RC BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC B1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 6 15
             run_exit_1RB0LB_0RC1LA_1LB0RD_1LC1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LB_0RC1LA_1LB0RD_1LC1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LB_0RC1LA_1LB0RD_1LC1RC t p (pow2 j)).
  - exists (6 * j + 5), (cden [] [] j BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC). split;
      [| exact (gbo_1RB0LB_0RC1LA_1LB0RD_1LC1RC j)].
    rewrite (gso_1RB0LB_0RC1LA_1LB0RD_1LC1RC p j E).
    exact (srun_sound tm true true chb_1RB0LB_0RC1LA_1LB0RD_1LC1RC B0_1RB0LB_0RC1LA_1LB0RD_1LC1RC BB1_1RB0LB_0RC1LA_1LB0RD_1LC1RC 6 5
             run_boot_1RB0LB_0RC1LA_1LB0RD_1LC1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LB_0RC1LA_1LB0RD_1LC1RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LB_0RC1LA_1LB0RD_1LC1RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LB_0RC1LA_1LB0RD_1LC1RC : forall t, ~ In t pins_1RB0LB_0RC1LA_1LB0RD_1LC1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LB_0RC1LA_1LB0RD_1LC1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LB_0RC1LA_1LB0RD_1LC1RC
