    apply (lap_of_run tm Cc true true cho_1RB0LB_0RC1LA_1LB1RD_1LB1RC B0_1RB0LB_0RC1LA_1LB1RD_1LB1RC B1_1RB0LB_0RC1LA_1LB1RD_1LB1RC 4 13 p j' [] []).
