Lemma gsi_1RB0LB_0RC1LA_1RD1RC_1LB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0LB_0RC1LA_1RD1RC_1LB0LC.
